sp_widget.client_script:
api.controller = function($scope, $interval) {
  var c = this;

  // Poll server every 20 seconds to catch real-time state advancements
  if (c.data && c.data.hasRecord) {
    var timer = $interval(function() {
      c.data.action = 'refreshStatus';
      c.server.update();
    }, 20000);

    $scope.$on('$destroy', function() {
      $interval.cancel(timer);
    });
  }
};

sp_widget.css:
.gvft-status-container {
  background-color: #1e4587;
  color: #ffffff;
  min-height: 100vh;
  padding: 40px 60px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-sizing: border-box;
}

/* Header */
.status-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 25px;
  max-width: 950px;
}

.badge-case {
  background: #38bdf8;
  color: #0c4a6e;
  padding: 4px 10px;
  font-weight: 700;
  border-radius: 4px;
  font-size: 13px;
  display: inline-block;
  margin-bottom: 8px;
}

.applicant-name {
  font-size: 32px;
  font-weight: 600;
  margin: 0 0 6px 0;
  color: #ffffff;
}

.role-sub {
  color: #cbd5e1;
  font-size: 14px;
  margin: 0;
}

.bullet-sep {
  margin: 0 8px;
  color: #64748b;
}

.status-pill {
  padding: 6px 16px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  background: rgba(255, 255, 255, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.status-submitted { background-color: #0284c7; }
.status-under_review { background-color: #f59e0b; color: #1e293b; }
.status-pre_approved, .status-approved { background-color: #10b981; }

/* Progress Card & Percentage Indicator */
.progress-section-card {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 10px;
  padding: 24px 30px 20px 30px;
  margin-bottom: 25px;
  max-width: 950px;
}

.progress-header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.progress-title {
  font-size: 15px;
  font-weight: 600;
  color: #e2e8f0;
}

.percentage-badge {
  background: #38bdf8;
  color: #0c4a6e;
  font-weight: 700;
  font-size: 14px;
  padding: 4px 12px;
  border-radius: 12px;
}

.progress-bar-track {
  height: 10px;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 5px;
  overflow: hidden;
  margin-bottom: 28px;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #38bdf8, #0ea5e9);
  border-radius: 5px;
  transition: width 0.6s ease-in-out;
}

/* Stepper Nodes */
.stages-wrapper {
  display: flex;
  justify-content: space-between;
}

.stage-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 120px;
}

.node-circle {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #1e3a8a;
  border: 2px solid rgba(255, 255, 255, 0.4);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 8px;
}

.stage-node.active .node-circle {
  background: #38bdf8;
  color: #0c4a6e;
  border-color: #38bdf8;
}

.stage-node.current .node-circle {
  box-shadow: 0 0 0 5px rgba(56, 189, 248, 0.3);
}

.node-title {
  font-size: 12px;
  color: #94a3b8;
  text-align: center;
  font-weight: 500;
}

.stage-node.active .node-title {
  color: #ffffff;
  font-weight: 600;
}

/* Metrics Grid */
.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  max-width: 950px;
  margin-bottom: 25px;
}

.metric-card {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  padding: 18px;
}

.metric-card label {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  color: #94a3b8;
  margin-bottom: 6px;
}

.metric-value {
  font-size: 15px;
  font-weight: 600;
  color: #ffffff;
}

.text-success { color: #4ade80 !important; }
.text-warning { color: #fde047 !important; }
.code-font { font-family: monospace; font-size: 14px; }
.uppercase { text-transform: uppercase; }

/* Verification Table */
.checklist-card {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  padding: 20px;
  max-width: 950px;
}

.checklist-title {
  font-size: 16px;
  font-weight: 600;
  margin: 0 0 15px 0;
  color: #ffffff;
}

.custom-table {
  width: 100%;
  border-collapse: collapse;
}

.custom-table th {
  color: #94a3b8;
  font-size: 12px;
  text-transform: uppercase;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding: 8px 12px;
}

.custom-table td {
  padding: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  font-size: 13.5px;
}

.label-status {
  display: inline-block;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 500;
}

.status-verified {
  background: rgba(74, 222, 128, 0.15);
  color: #4ade80;
  border: 1px solid rgba(74, 222, 128, 0.3);
}

/* Empty State */
.empty-state-card {
  text-align: center;
  padding: 80px 20px;
  max-width: 600px;
  margin: 0 auto;
}

.empty-icon {
  font-size: 54px;
  color: rgba(255, 255, 255, 0.3);
  margin-bottom: 16px;
}

.empty-title {
  font-size: 22px;
  margin-bottom: 8px;
}

.empty-desc {
  font-size: 14px;
  color: #cbd5e1;
  margin-bottom: 24px;
}

.btn-start {
  background: #38bdf8;
  color: #0c4a6e;
  font-weight: 600;
  padding: 10px 22px;
  border-radius: 6px;
  text-decoration: none;
  display: inline-block;
}
/* Dynamic Document Status Colors */
.status-verified, 
.status-approved {
  background: rgba(74, 222, 128, 0.15);
  color: #4ade80;
  border: 1px solid rgba(74, 222, 128, 0.3);
}

.status-submitted, 
.status-pending, 
.status-in_review {
  background: rgba(253, 224, 71, 0.15);
  color: #fde047;
  border: 1px solid rgba(253, 224, 71, 0.3);
}

.status-rejected {
  background: rgba(248, 113, 113, 0.15);
  color: #f87171;
  border: 1px solid rgba(248, 113, 113, 0.3);
}

.review-notes-cell {
  font-size: 13px;
  color: #cbd5e1;
  font-style: italic;
}

sp_widget.script:
(function() {
  var caseTable = 'x_2023506_german_1_imm_case';
  var docTable  = 'x_2023506_german_1_case_doc';

  // Fallback map for u_document_name: numeric value -> human label
  // Used when getDisplayValue returns raw value or empty
  var DOC_NAME_MAP = {
    '1': 'Passport',
    '2': 'Passport Photo',
    '3': 'Job Contract',
    '4': 'Degree Certificate',
    'passport': 'Passport',
    'Passport': 'Passport',
    'degree_certificate': 'Degree Certificate',
    'Degree Certificate': 'Degree Certificate',
    'power_of_attorney': 'Power of Attorney',
    'Power of Attorney': 'Power of Attorney',
    'job_contract': 'Job Contract',
    'Job Contract': 'Job Contract',
    'Passport Photo': 'Passport Photo'
  };

  // Resolve document name with fallback
  function resolveDocName(grDoc) {
    var displayVal = grDoc.getDisplayValue('u_document_name') + '';
    var rawVal     = grDoc.getValue('u_document_name') + '';

    // If getDisplayValue returned something different from raw, trust it
    if (displayVal && displayVal !== rawVal && displayVal.length > 0) {
      return displayVal.trim();
    }
    // Otherwise look up in fallback map
    if (DOC_NAME_MAP[rawVal]) {
      return DOC_NAME_MAP[rawVal];
    }
    if (DOC_NAME_MAP[displayVal]) {
      return DOC_NAME_MAP[displayVal];
    }
    // Last resort: return whatever we have
    return displayVal.trim() || rawVal.trim() || 'Required Document';
  }

  var sysId = $sp.getParameter('sys_id');
  var caseNum = $sp.getParameter('case');
  var grCase = new GlideRecord(caseTable);
  var found = false;

  // Try sys_id first
  if (sysId && grCase.get(sysId)) {
    found = true;
  }

  // Try case number
  if (!found && caseNum) {
    grCase = new GlideRecord(caseTable);
    grCase.addQuery('number', caseNum);
    grCase.setLimit(1);
    grCase.query();
    if (grCase.next()) {
      found = true;
    }
  }

  // Fallback: latest case by email
  if (!found) {
    var userId = gs.getUserID();
    if (userId) {
      var userGr = new GlideRecord('sys_user');
      if (userGr.get(userId)) {
        var userEmail = userGr.getValue('email') + '';
        if (userEmail) {
          grCase = new GlideRecord(caseTable);
          grCase.addQuery('u_candidate_email', userEmail);
          grCase.orderByDesc('sys_created_on');
          grCase.setLimit(1);
          grCase.query();
          if (grCase.next()) {
            found = true;
          }
        }
      }
    }
  }

  // Last fallback: most recent case
  if (!found) {
    grCase = new GlideRecord(caseTable);
    grCase.orderByDesc('sys_created_on');
    grCase.setLimit(1);
    grCase.query();
    if (grCase.next()) {
      found = true;
    }
  }

  if (found && grCase.isValidRecord()) {
    data.hasRecord = true;
    data.sysId = grCase.getUniqueValue();
    data.number = grCase.getValue('number') + '';
    data.candidateName = (grCase.getValue('u_candidate_name') || 'Applicant') + '';
    data.city = (grCase.getValue('u_target_city') || 'Germany') + '';
    data.category = (grCase.getDisplayValue('u_visa_category') || 'EU Blue Card') + '';
    data.state = (grCase.getDisplayValue('state') || 'Open') + '';
    data.feeStatus = (grCase.getDisplayValue('u_fee_status') || 'Pending') + '';
    data.approvalNumber = (grCase.getValue('u_approval_number') || '') + '';
    data.passportNumber = (grCase.getValue('u_passport_number') || '') + '';

    var stateVal = (grCase.getValue('state') || '1') + '';
    data.stateKey = data.state.toLowerCase().replace(/\s+/g, '_');

    // Progress calculation based on task state
    if (stateVal === '3') {
      data.percent = 100;
      data.stageIndex = 4;
    } else if (stateVal === '2') {
      data.percent = 60;
      data.stageIndex = 2;
    } else {
      data.percent = 25;
      data.stageIndex = 1;
    }

    // Load Document Verification Matrix
    data.documents = [];
    var grDoc = new GlideRecord(docTable);
    grDoc.addQuery('u_case', data.sysId);
    grDoc.orderBy('u_document_name');
    grDoc.setLimit(20);
    grDoc.query();

    while (grDoc.next()) {
      var docStatusDisplay = (grDoc.getDisplayValue('u_status') || 'Pending') + '';
      var docStatusRaw = (grDoc.getValue('u_status') || 'pending') + '';

      data.documents.push({
        name: resolveDocName(grDoc),
        status: docStatusDisplay.trim(),
        statusKey: docStatusRaw.toLowerCase().replace(/\s+/g, '_'),
        notes: (grDoc.getValue('u_review_notes') || '') + ''
      });
    }

  } else {
    data.hasRecord = false;
  }
})();
